mapper.select:
SELECT e.*, d.dept_name AS deptName, p.post_name AS postName, p.base_salary AS postBaseSalary, l.level_name AS levelName, r.role_name AS roleName FROM employee e LEFT JOIN dept d ON e.dept_id = d.id LEFT JOIN post p ON e.post_id = p.id LEFT JOIN level l ON e.level_id = l.id LEFT JOIN role r ON e.role_id = r.id
AND e.dept_id = #{deptId}
AND e.post_id = #{postId}
AND e.name LIKE CONCAT('%', #{name}, '%')
